#[derive(Clone,Copy,Debug,Default,PartialEq)]pub struct Vec2{pub x:f64,pub y:f64}
impl Vec2{pub fn add(self,b:Self)->Self{Self{x:self.x+b.x,y:self.y+b.y}}pub fn sub(self,b:Self)->Self{Self{x:self.x-b.x,y:self.y-b.y}}pub fn scale(self,k:f64)->Self{Self{x:self.x*k,y:self.y*k}}pub fn rotate(self,a:f64)->Self{let(c,s)=(a.cos(),a.sin());Self{x:self.x*c-self.y*s,y:self.x*s+self.y*c}}pub fn len(self)->f64{length(self.x,self.y)}pub fn angle(self)->f64{self.y.atan2(self.x)}pub fn add_scaled(self,b:Self,k:f64)->Self{Self{x:self.x+b.x*k,y:self.y+b.y*k}}}
