    fn carrier<H:Host>(&self,host:&H,craft:Identity,player:Identity,enemy:Identity)->Result<Identity,Error>{let b=host.body_shared(craft)?;Ok(b.wing.as_deref().and_then(|id|self.wing(id)).map_or(if b.player{player}else{enemy},|w|w.carrier))}
    fn range<H:Host>(&self,host:&H,craft:Identity,carrier:Identity)->Result<f64,Error>{let mult=host.carrier_stats(carrier)?.range_multiplier;if mult<=0.0{return Ok(0.0);}Ok(self.craft_wing(host,craft)?.and_then(|w|w.spec.range).unwrap_or(f64::INFINITY)*mult)}
    fn operational<H:Host>(host:&H,carrier:Identity)->Result<bool,Error>{let c=host.body_shared(carrier)?;Ok(c.alive()&&host.body_shared(c.root)?.alive())}
